diff --git a/client/src/components/ArticleCard.jsx b/client/src/components/ArticleCard.jsx
index cca3cc5..940ff12 100644
--- a/client/src/components/ArticleCard.jsx
+++ b/client/src/components/ArticleCard.jsx
@@ -24,9 +24,9 @@ function ErrorToast({ message, onDismiss }) {
 }

 function ZenModeOverlay({ url, html, hostname, displayDomain, articleMeta, onClose, onMarkDone }) {
-  const [hasScrolled, setHasScrolled] = useState(false)
   const scrollRef = useRef(null)
   const progress = useScrollProgress(scrollRef)
+  const [hasScrolled, setHasScrolled] = useState(false)

   useEffect(() => {
     document.body.style.overflow = 'hidden'
@@ -50,61 +50,63 @@ function ZenModeOverlay({ url, html, hostname, displayDomain, articleMeta, onClo

   return createPortal(
     <div className="fixed inset-0 z-[100]">
-      <div className="w-full h-full bg-white relative animate-zen-enter">
-        {/* Absolute Header */}
-        <div
-          className={`
-            absolute top-0 left-0 right-0 z-10
-            flex items-center justify-between p-4
-            transition-all duration-200
-            ${hasScrolled ? 'bg-white/80 backdrop-blur-md border-b border-slate-100' : 'bg-transparent'}
-          `}
-        >
+      <div className="w-full h-full bg-white animate-zen-enter relative">
+        {/* Header: absolute positioned for transparency effect */}
+        <div className={`
+          absolute top-0 left-0 right-0 z-10
+          flex items-center justify-between px-5 py-4 transition-all duration-200
+          ${hasScrolled
+            ? 'bg-white/80 backdrop-blur-md border-b border-slate-100'
+            : 'bg-transparent border-b border-transparent'}
+        `}>
+          {/* Left: Collapse (Down Chevron) */}
           <button
             onClick={onClose}
-            className="shrink-0 p-2 rounded-full hover:bg-slate-200/80 text-slate-500 hover:text-slate-700 transition-colors"
+            className="p-2 -ml-2 rounded-full hover:bg-slate-200/60 text-slate-500 hover:text-slate-700 transition-colors"
+            aria-label="Close and save for later"
           >
             <ChevronDown size={20} />
           </button>

-          <a
-            href={url}
-            target="_blank"
-            rel="noopener noreferrer"
-            className="flex items-center gap-2 hover:opacity-70 transition-opacity"
-          >
+          {/* Center: Source Context */}
+          <div className="flex items-center gap-2">
             {hostname && (
-              <img
-                src={`https://www.google.com/s2/favicons?domain=${hostname}&sz=64`}
-                className="w-[18px] h-[18px] rounded-full border border-slate-200"
-                alt=""
-              />
+              <div className="w-[18px] h-[18px] rounded-full bg-white border border-slate-200 overflow-hidden flex items-center justify-center shrink-0">
+                <img
+                  src={`https://www.google.com/s2/favicons?domain=${hostname}&sz=64`}
+                  alt={displayDomain}
+                  className="w-full h-full object-cover"
+                  onError={(e) => { e.target.style.display = 'none' }}
+                />
+              </div>
             )}
             <span className="text-sm text-slate-500 font-medium">
               {displayDomain}
               {articleMeta && <span className="text-slate-400"> · {articleMeta}</span>}
             </span>
-          </a>
+          </div>

+          {/* Right: Mark Done (Checkmark) */}
           <button
             onClick={onMarkDone}
-            className="shrink-0 p-2 rounded-full hover:bg-green-100 text-slate-500 hover:text-green-600 transition-colors"
+            className="p-2 -mr-2 rounded-full hover:bg-green-100 text-slate-400 hover:text-green-600 transition-colors"
+            aria-label="Mark as done and remove"
           >
             <Check size={20} />
           </button>

-          {/* Progress Bar */}
+          {/* Progress bar at bottom of header */}
           <div
-            className="absolute bottom-0 left-0 right-0 h-0.5 bg-purple-500 origin-left transition-transform duration-100"
+            className="absolute bottom-0 left-0 h-0.5 bg-purple-500 origin-left transition-transform duration-100"
             style={{ transform: `scaleX(${progress})` }}
           />
         </div>

-        {/* Content Area with Padding */}
-        <div ref={scrollRef} className="overflow-y-auto h-full pt-16 p-6 md:p-8 bg-white">
+        {/* Content: pt-[4.25rem] balances spacing below header */}

